          repo: a.repo,
          owner: a.owner,
          ownerFromToken: a.ownerFromToken === true,
          category: a.category,
          descriptionEn: a.descriptionEn,
          descriptionZh: a.descriptionZh,
          dryRun: a.dryRun !== false,
