          const lines = [`slipway_verify｜${d.ok === true ? '✅ 线上与本地逐字节一致' : '❌ 有不一致'}`];
          lines.push(`  · 目标：${d.owner}/${d.repo}`);
          lines.push(`  · 比对：${d.checked} 个文件通过`);
